#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int maxn = 505;
int n, m, mod;
inline int sum_mod(int x, int y) {
    int s = x + y;
    if (s >= mod) s -= mod;
    return s;
}
inline int product_mod(int x, int y) { return (ll) x * y % mod; }
int C[maxn][maxn];
int f[maxn], g[maxn];
int F[maxn][maxn], G[maxn][maxn];

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = sum_mod(C[i - 1][j - 1], C[i - 1][j]);
        }
    }
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            int val1 = product_mod(product_mod(f[j - 1], f[i - j]), product_mod(i + 1, C[i - 1][j - 1]));
            f[i] = sum_mod(f[i], val1);
            int val2 = product_mod(product_mod(f[j - 1], g[i - j]), product_mod(i + 1, C[i - 1][j - 1]));
            g[i] = sum_mod(g[i], val2);
            int val3 = product_mod(product_mod(g[j - 1], f[i - j]), product_mod(i + 1, C[i - 1][j - 1]));
            g[i] = sum_mod(g[i], val3);
            int val4 = product_mod(product_mod(f[j - 1], f[i - j]), product_mod(sum_mod(C[j][2], C[i - j + 1][2]), C[i - 1][j - 1]));
            g[i] = sum_mod(g[i], val4);
        }
    }
    F[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (int j = 0; j <= min(i - 1, m); j++) {
            for (int l = 0; l <= j; l++) {
                G[i][j] = sum_mod(G[i][j], product_mod(product_mod(g[l], F[i - l - 1][j - l]), C[j][l]));
                F[i][j] = sum_mod(F[i][j], product_mod(product_mod(f[l], F[i - l - 1][j - l]), C[j][l]));
                G[i][j] = sum_mod(G[i][j], product_mod(product_mod(f[l], G[i - l - 1][j - l]), C[j][l]));
            }
        }
    }
    cout << G[n][m] << endl;
    return 0;
}
